import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static class Modular {
        final int val;

        public Modular(int val) {
            this.val = val % MOD;
            if (this.val < 0) this.val += MOD;
        }

        public Modular add(Modular other) {
            int sum = this.val + other.val;
            if (sum >= MOD) sum -= MOD;
            return new Modular(sum);
        }

        public Modular subtract(Modular other) {
            int diff = this.val - other.val;
            if (diff < 0) diff += MOD;
            return new Modular(diff);
        }

        public Modular multiply(Modular other) {
            long prod = (long) this.val * other.val % MOD;
            return new Modular((int) prod);
        }

        public Modular divide(Modular other) {
            return this.multiply(other.inverse());
        }

        public Modular inverse() {
            int a = this.val, b = MOD;
            int ax = 1, bx = 0;
            while (b != 0) {
                int q = a / b;
                int t = a % b;
                a = b;
                b = t;
                t = ax - bx * q;
                ax = bx;
                bx = t;
            }
            if (ax < 0) ax += MOD;
            return new Modular(ax);
        }

        public Modular pow(long p) {
            Modular result = new Modular(1);
            Modular base = this;
            while (p > 0) {
                if ((p & 1) == 1) result = result.multiply(base);
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        public static final Modular ZERO = new Modular(0);
        public static final Modular ONE = new Modular(1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        Modular[] prob = new Modular[N * N];
        Modular inv100 = Modular.ONE.divide(new Modular(100));
        for (int i = 0; i < N * N; i++) {
            int x = sc.nextInt();
            prob[i] = inv100.multiply(new Modular(x));
        }

        int mid = N / 2;
        int[] maskToIdx = new int[1 << 6];
        int idxCount = 0;
        for (int mask = 0; mask < (1 << 6); mask++) {
            if (Integer.bitCount(mask) == mid) {
                maskToIdx[mask] = idxCount++;
            } else {
                maskToIdx[mask] = -1;
            }
        }
        int totalSize = 1 << idxCount;
        Modular[] total = new Modular[totalSize];
        for (int i = 0; i < totalSize; i++) total[i] = Modular.ZERO;

        // Process first half
        int left = 0, right = mid;
        int len = right - left;
        int edgeLimit = 1 << (len * N);
        for (int edge = 0; edge < edgeLimit; edge++) {
            Modular p = Modular.ONE;
            int shift = edge;
            boolean skip = false;
            for (int pos = left * N; pos < right * N; pos++, shift >>= 1) {
                Modular term = ((shift & 1) == 1) ? prob[pos] : Modular.ONE.subtract(prob[pos]);
                p = p.multiply(term);
                if (p.val == 0) {
                    skip = true;
                    break;
                }
            }
            if (skip) continue;

            int sets = 0;
            int totalComb = 1;
            for (int i = 0; i < len; i++) totalComb *= N;
            for (int comb = 0; comb < totalComb; comb++) {
                int mm = 0;
                boolean ok = true;
                int temp = comb;
                for (int i = 0; i < len; i++) {
                    int digit = temp % N;
                    temp /= N;
                    int pos = i * N + digit;
                    if (((edge >> pos) & 1) == 0) {
                        ok = false;
                        break;
                    }
                    if ((mm & (1 << digit)) != 0) {
                        ok = false;
                        break;
                    }
                    mm |= (1 << digit);
                }
                if (ok) {
                    if (right == N) mm ^= (1 << N) - 1;
                    int idx = maskToIdx[mm];
                    if (idx != -1) sets |= (1 << idx);
                }
            }
            total[sets] = total[sets].add(p);
        }

        // SOS DP
        for (int d = 1; d < totalSize; d <<= 1) {
            for (int i = 0; i < totalSize; i++) {
                if ((i & d) == 0) {
                    total[i | d] = total[i | d].add(total[i]);
                }
            }
        }

        // Process second half
        left = mid;
        right = N;
        len = right - left;
        edgeLimit = 1 << (len * N);
        Modular ans = Modular.ZERO;
        for (int edge = 0; edge < edgeLimit; edge++) {
            Modular p = Modular.ONE;
            int shift = edge;
            boolean skip = false;
            for (int pos = left * N; pos < right * N; pos++, shift >>= 1) {
                Modular term = ((shift & 1) == 1) ? prob[pos] : Modular.ONE.subtract(prob[pos]);
                p = p.multiply(term);
                if (p.val == 0) {
                    skip = true;
                    break;
                }
            }
            if (skip) continue;

            int sets = 0;
            int totalComb = 1;
            for (int i = 0; i < len; i++) totalComb *= N;
            for (int comb = 0; comb < totalComb; comb++) {
                int mm = 0;
                boolean ok = true;
                int temp = comb;
                for (int i = 0; i < len; i++) {
                    int digit = temp % N;
                    temp /= N;
                    int pos = i * N + digit;
                    if (((edge >> pos) & 1) == 0) {
                        ok = false;
                        break;
                    }
                    if ((mm & (1 << digit)) != 0) {
                        ok = false;
                        break;
                    }
                    mm |= (1 << digit);
                }
                if (ok) {
                    if (right == N) mm ^= (1 << N) - 1;
                    int idx = maskToIdx[mm];
                    if (idx != -1) sets |= (1 << idx);
                }
            }
            ans = ans.add(p.multiply(total[totalSize - 1].subtract(total[totalSize - 1 - sets])));
        }

        System.out.println(ans.val);
    }
}
